window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ee148cf58fcb4d4d"]={"versions": [{"id": "FIG-ee148cf58fcb4d4d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Datenflussdiagramm des AUTOSAR Diagnostic Event Managers (Dem) zur Veranschaulichung des Pufferungsverhaltens bei Fehlerstatus-Meldungen (<code>Dem_ReportErrorStatus</code>) in verschiedenen Betriebsphasen (Startup vs. Normalbetrieb).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dem (Diagnostic Event Manager)</strong>: BSW-Modulblock, der die interne Verarbeitungslogik kapselt.\n</li><li><strong>API</strong>: Direkte C-API-Schnittstelle (<code>Dem_ReportErrorStatus</code>) am Modulrand.\n</li><li><strong>Port</strong>: AUTOSAR-Port-Schnittstelle (z. B. <code>DiagnosticMonitor</code>) am Modulrand für Software-Komponenten (SWCs).\n</li><li><strong>Buffer</strong>: Zwischenspeicher für vorzeitig gemeldete Fehlerstatus-Events während der Initialisierungs- bzw. Startphase.\n</li><li><strong>Event Memory</strong>: Primärer Ereignisspeicher zur persistenten und qualifizierten Ablage diagnostischer Events.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Über die C-API eingehende Meldungen werden sowohl während des Startups als auch während des Normalbetriebs entgegengenommen (<code>available during startup (and normal operation)</code>) und in den internen <code>Buffer</code> geleitet.\n</li><li>Die Übernahme der gepufferten Events in den <code>Event Memory</code> erfolgt asynchron getrieben durch <code>Dem_Init()</code> bzw. zyklisch über <code>Dem_MainFunction()</code>.\n</li><li>Über AUTOSAR-Ports gemeldete Ereignisse stehen erst im Normalbetrieb zur Verfügung (<code>available during normal operation</code>) und adressieren den <code>Event Memory</code> direkt.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>BSW-Module können Fehler bereits vor vollständiger Dem-Initialisierung über die C-API melden, ohne dass Events verloren gehen.\n</li><li>SWC-basierte Monitore über RTE-Ports dürfen erst nach Betriebsbereitschaft des Dem aktiv melden.\n</li><li>Systemintegratoren müssen die Puffergröße für Startup-Events ausreichend dimensionieren, um Pufferüberläufe bis zum ersten Lauf von <code>Dem_MainFunction()</code> bzw. nach <code>Dem_Init()</code> zu vermeiden.\n</li></ul>"}, {"id": "FIG-f8bef9e3316d9f13", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Datenflussdiagramm des AUTOSAR Diagnostic Event Managers (Dem) zur Veranschaulichung des Pufferungsverhaltens bei Fehlerstatus-Meldungen (<code>Dem_ReportErrorStatus</code>) in verschiedenen Betriebsphasen (Startup vs. Normalbetrieb).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Dem (Diagnostic Event Manager)</strong>: BSW-Modulblock, der die interne Verarbeitungslogik kapselt.\n</li><li><strong>API</strong>: Direkte C-API-Schnittstelle (<code>Dem_ReportErrorStatus</code>) am Modulrand.\n</li><li><strong>Port</strong>: AUTOSAR-Port-Schnittstelle (z. B. <code>DiagnosticMonitor</code>) am Modulrand für Software-Komponenten (SWCs).\n</li><li><strong>Buffer</strong>: Zwischenspeicher für vorzeitig gemeldete Fehlerstatus-Events während der Initialisierungs- bzw. Startphase.\n</li><li><strong>Event Memory</strong>: Primärer Ereignisspeicher zur persistenten und qualifizierten Ablage diagnostischer Events.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Über die C-API eingehende Meldungen werden sowohl während des Startups als auch während des Normalbetriebs entgegengenommen (<code>available during startup (and normal operation)</code>) und in den internen <code>Buffer</code> geleitet.\n</li><li>Die Übernahme der gepufferten Events in den <code>Event Memory</code> erfolgt asynchron getrieben durch <code>Dem_Init()</code> bzw. zyklisch über <code>Dem_MainFunction()</code>.\n</li><li>Über AUTOSAR-Ports gemeldete Ereignisse stehen erst im Normalbetrieb zur Verfügung (<code>available during normal operation</code>) und adressieren den <code>Event Memory</code> direkt.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>BSW-Module können Fehler bereits vor vollständiger Dem-Initialisierung über die C-API melden, ohne dass Events verloren gehen.\n</li><li>SWC-basierte Monitore über RTE-Ports dürfen erst nach Betriebsbereitschaft des Dem aktiv melden.\n</li><li>Systemintegratoren müssen die Puffergröße für Startup-Events ausreichend dimensionieren, um Pufferüberläufe bis zum ersten Lauf von <code>Dem_MainFunction()</code> bzw. nach <code>Dem_Init()</code> zu vermeiden.\n</li></ul>"}], "trans": [{"from": "FIG-ee148cf58fcb4d4d", "to": "FIG-f8bef9e3316d9f13", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
